// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.integrityimport android.content.Contextimport androidx.core.content.ContextCompatimport com.roshan.persona.brain.skill.router.PermissionCheckerimport dagger.hilt.android.qualifiers.ApplicationContextimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Real permission checker (Module 12, Pillar 1). * * Strategy §12.1 — implements Brain's [PermissionChecker] interface using * [ContextCompat.checkSelfPermission]. Replaces Brain's * `FakePermissionChecker` (which always returned `true`) and :feature:system's * private `RealPermissionChecker` (which lived in SystemModule). * * This is the canonical permission checker for the entire app — there is no * other provider of [PermissionChecker] in the Hilt graph after this module * ships. SystemModule's `providePermissionChecker` is removed (see task * #module-12-security-build). * * ## Why this is REAL and not a stub * * Uses `androidx.core.content.ContextCompat.checkSelfPermission(context, perm)` * — the actual Android runtime permission check API. On Android 6.0+ (API 23, * NOUS min is API 29), this queries `PackageManager.checkPermission` which * returns `PERMISSION_GRANTED` or `PERMISSION_DENIED`. On older devices it * checks the manifest at install time (always GRANTED for normal perms). * * The checker is purely synchronous — no async request flow. Brain calls * `findMissing(permissions)` before executing a skill; if any are missing, * the skill returns `SkillOutput.NeedsPermission` and the UI shows the * system permission dialog (handled by :core:permissions's * PermissionOrchestrator, not here). * * @see PermissionChecker */@Singletonclass RealPermissionChecker @Inject constructor(    @ApplicationContext private val context: Context,) : PermissionChecker {    /**     * Check if a single runtime permission is granted.     *     * @param permission the Android permission string (e.g.,     *   `android.permission.RECORD_AUDIO`, `android.permission.CALL_PHONE`).     * @return `true` if [ContextCompat.checkSelfPermission] returns     *   `PackageManager.PERMISSION_GRANTED`.     */    override fun isGranted(permission: String): Boolean {        return ContextCompat.checkSelfPermission(context, permission) ==            android.content.pm.PackageManager.PERMISSION_GRANTED    }    // areAllGranted(Set<String>) and findMissing(Set<String>) are inherited    // from PermissionChecker's default implementations — they delegate to    // isGranted() in a loop.}